create schema if not exists extensions;
create schema if not exists private;
create extension if not exists postgis with schema extensions;
create extension if not exists pg_trgm with schema extensions;
create extension if not exists pgcrypto with schema extensions;
create extension if not exists pg_cron;
create type public.listing_status as enum ('for_sale','pending','sold');
create type public.feature_group as enum ('interior','area_lot','exterior','financial');
create type public.lead_source as enum ('contact','valuation','showing','newsletter','agent','progressive');
create type public.lead_status as enum ('new','contacted','closed');
create type public.consent_channel as enum ('email_phone','sms','newsletter');
create type public.profile_role as enum ('user','agent','admin');
create table public.site_settings (id uuid primary key default gen_random_uuid(),key text unique not null,value jsonb not null);
create table public.agents (id uuid primary key default gen_random_uuid(),slug text unique not null,full_name text not null,title text not null,bio text not null default '',photo_path text,email text,phone text,license_no text,socials jsonb default '{}',sort_order int default 0,is_active boolean default true);
create table public.neighborhoods (id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,blurb text,hero_path text,boundary extensions.geography(MultiPolygon,4326),sort_order int default 0,lat double precision,lng double precision);
create table public.listings (id uuid primary key default gen_random_uuid(),mls_id text unique not null,slug text unique not null,status public.listing_status not null,list_price numeric not null check(list_price>=0),sold_price numeric,sold_date date,property_type text not null,beds int default 0,baths_full int default 0,baths_half int default 0,living_sqft numeric default 0,lot_acres numeric default 0,year_built int,stories int,address_line text not null,city text not null,state text default 'AR',zip text,neighborhood_id uuid references public.neighborhoods,geom extensions.geography(Point,4326),lat double precision,lng double precision,description text,listing_agent_id uuid references public.agents,courtesy_of text,is_featured boolean default false,featured_rank int default 999,hidden boolean default false,raw jsonb default '{}',synced_at timestamptz default now());
create table public.listing_photos (id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.listings on delete cascade,url text,storage_path text,caption text,sort_order int default 0,width int,height int,blurhash text);
create table public.listing_features (id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.listings on delete cascade,"group" public.feature_group not null,label text not null,value text);
create table public.neighborhood_stats (id uuid primary key default gen_random_uuid(),neighborhood_id uuid not null references public.neighborhoods on delete cascade,source text not null,payload jsonb not null,fetched_at timestamptz default now(),unique(neighborhood_id,source));
create table public.neighborhood_pois (id uuid primary key default gen_random_uuid(),neighborhood_id uuid not null references public.neighborhoods on delete cascade,name text not null,category text,address text,lat double precision,lng double precision,distance_mi numeric,review_count int default 0,rating numeric,yelp_url text,fetched_at timestamptz default now());
create table public.schools (id uuid primary key default gen_random_uuid(),neighborhood_id uuid not null references public.neighborhoods on delete cascade,name text not null,level text,category text,grades text,rating numeric);
create table public.testimonials (id uuid primary key default gen_random_uuid(),reviewer_name text not null,body text not null,rating numeric,agent_id uuid references public.agents,source text,is_featured boolean default false,sort_order int default 0);
create table public.blog_posts (id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,excerpt text,body_md text,cover_path text,category text,author_id uuid references public.agents,status text check(status in ('draft','published')) default 'draft',published_at timestamptz,seo jsonb default '{}');
create table public.social_posts (id uuid primary key default gen_random_uuid(),image_path text not null,permalink text not null,alt text not null,sort_order int default 0);
create table public.profiles (id uuid primary key references auth.users on delete cascade,email text,full_name text,phone text,role public.profile_role not null default 'user',notification_prefs jsonb default '{}');
create table public.leads (id uuid primary key default gen_random_uuid(),source public.lead_source not null,first_name text,middle_name text,last_name text,email text not null,phone text,interest text,message text,listing_id uuid references public.listings,agent_id uuid references public.agents,trigger_source text,utm jsonb default '{}',ip_hash text,user_agent text,status public.lead_status default 'new',assigned_to uuid references public.profiles,notes text default '');
create table public.consents (id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.leads,channel public.consent_channel not null,granted boolean not null,disclosure_text text not null,disclosure_version text not null,ip_hash text,user_agent text,granted_at timestamptz default now());
create table public.showing_requests (id uuid primary key default gen_random_uuid(),listing_id uuid not null references public.listings,lead_id uuid not null references public.leads,starts_at timestamptz not null,meeting_type text check(meeting_type in ('in_person','video')),status text default 'requested');
create table public.valuation_requests (id uuid primary key default gen_random_uuid(),lead_id uuid not null references public.leads,address text not null,geom extensions.geography(Point,4326),lat double precision,lng double precision,result jsonb,confidence text);
create table public.newsletter_subscribers (id uuid primary key default gen_random_uuid(),email text unique not null,status text default 'pending',confirmed_at timestamptz);
create table public.saved_homes (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,listing_id uuid not null references public.listings on delete cascade,unique(user_id,listing_id));
create table public.saved_searches (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,name text not null,filters jsonb not null,polygon extensions.geography(MultiPolygon,4326),frequency text check(frequency in ('instant','daily','weekly')),channels text[] default '{email}',last_sent_at timestamptz);
create table public.redirects (id uuid primary key default gen_random_uuid(),from_path text unique not null,to_path text not null,status_code int default 301 check(status_code in (301,302,307,308)));
create table public.audit_log (id uuid primary key default gen_random_uuid(),actor_id uuid,action text not null,table_name text not null,record_id text,changes jsonb);
create table public.dev_outbox (id uuid primary key default gen_random_uuid(),channel text not null,recipient text not null,subject text,body text,attachments jsonb default '[]',sent_at timestamptz);
create table private.rate_limits (key text primary key,hits int not null,window_start timestamptz not null);
create function private.touch_updated_at() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now();return new;end$$;
do $$declare t text;begin foreach t in array array['site_settings','agents','neighborhoods','listings','listing_photos','listing_features','neighborhood_stats','neighborhood_pois','schools','testimonials','blog_posts','social_posts','profiles','leads','consents','showing_requests','valuation_requests','newsletter_subscribers','saved_homes','saved_searches','redirects','audit_log','dev_outbox'] loop execute format('alter table public.%I add column created_at timestamptz not null default now(), add column updated_at timestamptz not null default now()',t);execute format('alter table public.%I enable row level security',t);execute format('create trigger touch_updated before update on public.%I for each row execute function private.touch_updated_at()',t);end loop;end$$;
alter table private.rate_limits enable row level security;
create index listings_geo_idx on public.listings using gist(geom);
create index neighborhoods_geo_idx on public.neighborhoods using gist(boundary);
create index listings_address_idx on public.listings using gin(address_line extensions.gin_trgm_ops);
create index listings_status_price_idx on public.listings(status,list_price) where not hidden;
create index listings_featured_idx on public.listings(featured_rank,list_price desc) where is_featured and not hidden;
create index listings_neighborhood_idx on public.listings(neighborhood_id);
create index listings_agent_idx on public.listings(listing_agent_id);
create index photos_listing_idx on public.listing_photos(listing_id,sort_order);
create index features_listing_idx on public.listing_features(listing_id);
create index leads_email_idx on public.leads(email);
create index leads_status_source_idx on public.leads(status,source,created_at desc);
create index consents_lead_idx on public.consents(lead_id,granted_at desc);
create index saved_homes_user_idx on public.saved_homes(user_id);
create index saved_searches_user_idx on public.saved_searches(user_id);
create index showings_lead_idx on public.showing_requests(lead_id);
create index valuation_lead_idx on public.valuation_requests(lead_id);
create function private.is_staff() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=(select auth.uid()) and role in ('admin','agent'))$$;
revoke all on function private.is_staff() from public;
grant usage on schema private to authenticated;
grant execute on function private.is_staff() to authenticated;
create policy public_listings on public.listings for select to anon,authenticated using(not hidden);
create policy public_agents on public.agents for select to anon,authenticated using(is_active);
create policy public_blogs on public.blog_posts for select to anon,authenticated using(status='published');
create policy safe_settings on public.site_settings for select to anon,authenticated using(key in ('stats','contact','socials','seo','idx_last_synced_at'));
do $$declare t text;begin foreach t in array array['neighborhoods','listing_photos','listing_features','neighborhood_stats','neighborhood_pois','schools','testimonials','social_posts'] loop execute format('create policy public_read on public.%I for select to anon,authenticated using(true)',t);end loop;end$$;
create policy own_profile on public.profiles for select to authenticated using(id=(select auth.uid()) or (select private.is_staff()));
create policy edit_profile on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
do $$declare t text;begin foreach t in array array['saved_homes','saved_searches'] loop execute format('create policy own_rows on public.%I for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()))',t);end loop;end$$;
do $$declare t text;begin foreach t in array array['site_settings','agents','neighborhoods','listings','listing_photos','listing_features','neighborhood_stats','neighborhood_pois','schools','testimonials','blog_posts','social_posts','leads','showing_requests','valuation_requests','newsletter_subscribers','redirects','dev_outbox'] loop execute format('create policy staff_access on public.%I for all to authenticated using((select private.is_staff())) with check((select private.is_staff()))',t);end loop;end$$;
create policy staff_audit_read on public.audit_log for select to authenticated using((select private.is_staff()));
create policy staff_consents_read on public.consents for select to authenticated using((select private.is_staff()));
grant select on public.listings,public.agents,public.neighborhoods,public.listing_photos,public.listing_features,public.neighborhood_stats,public.neighborhood_pois,public.schools,public.testimonials,public.blog_posts,public.social_posts,public.site_settings to anon,authenticated;
grant select on public.profiles,public.consents,public.audit_log to authenticated;
grant update(full_name,phone,notification_prefs) on public.profiles to authenticated;
grant select,insert,update,delete on public.saved_homes,public.saved_searches to authenticated;
grant select,insert,update,delete on public.site_settings,public.agents,public.neighborhoods,public.listings,public.listing_photos,public.listing_features,public.neighborhood_stats,public.neighborhood_pois,public.schools,public.testimonials,public.blog_posts,public.social_posts,public.leads,public.showing_requests,public.valuation_requests,public.newsletter_subscribers,public.redirects,public.dev_outbox to authenticated;
grant all on all tables in schema public to service_role;
create function private.immutable_record() returns trigger language plpgsql set search_path='' as $$begin raise exception 'Audit records are immutable';end$$;
create trigger immutable_consents before update or delete on public.consents for each row execute function private.immutable_record();
create trigger immutable_audit before update or delete on public.audit_log for each row execute function private.immutable_record();
create function private.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,email,full_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',''));return new;end$$;
revoke all on function private.handle_new_user() from public;
create trigger on_auth_user_created after insert on auth.users for each row execute function private.handle_new_user();
create function public.listings_in_polygon(polygon jsonb) returns setof public.listings language sql stable security invoker set search_path='' as $$select * from public.listings where not hidden and extensions.st_contains(extensions.st_setsrid(extensions.st_geomfromgeojson(polygon),4326),geom::extensions.geometry)$$;
create function public.search_listings(filters jsonb default '{}',sort text default 'newest',page_limit int default 12,page_offset int default 0) returns jsonb language sql stable security invoker set search_path='' as $$with matches as(select * from public.listings l where not hidden and (coalesce(filters->>'status','')='' or l.status::text=filters->>'status') and (coalesce(filters->>'q','')='' or concat(l.address_line,' ',l.city,' ',l.zip,' ',l.mls_id) ilike '%'||(filters->>'q')||'%') and (coalesce(filters->>'type','')='' or l.property_type=filters->>'type') and l.list_price>=coalesce((filters->>'min')::numeric,0) and l.list_price<=coalesce((filters->>'max')::numeric,1e12) and l.beds>=coalesce((filters->>'beds')::int,0) and (l.baths_full+l.baths_half*.5)>=coalesce((filters->>'baths')::numeric,0) and l.living_sqft>=coalesce((filters->>'area')::numeric,0) and (filters->'polygon' is null or extensions.st_contains(extensions.st_setsrid(extensions.st_geomfromgeojson(filters->'polygon'),4326),l.geom::extensions.geometry))), page as(select * from matches order by case when sort='price-asc' then list_price end asc,case when sort='price-desc' then list_price end desc,case when sort='beds' then beds end desc,case when sort='sqft' then living_sqft end desc,created_at desc limit least(greatest(page_limit,1),100) offset greatest(page_offset,0)) select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(page)) from page),'[]'::jsonb),'total',(select count(*) from matches))$$;
create function public.comps_for_valuation(lat double precision,lng double precision,beds int,baths int,sqft numeric,type text) returns setof public.listings language sql stable security invoker set search_path='' as $$select * from public.listings l where l.status='sold' and not hidden and l.sold_date>current_date-interval '18 months' and l.property_type=type and abs(l.beds-beds)<=1 and abs(l.baths_full-baths)<=1 and l.living_sqft between sqft*.65 and sqft*1.35 and extensions.st_dwithin(l.geom,extensions.st_setsrid(extensions.st_makepoint(lng,lat),4326)::extensions.geography,16093) order by extensions.st_distance(l.geom,extensions.st_setsrid(extensions.st_makepoint(lng,lat),4326)::extensions.geography) limit 12$$;
create function public.similar_listings(listing_id uuid) returns setof public.listings language sql stable security invoker set search_path='' as $$select l.* from public.listings l join public.listings original on original.id=listing_id where l.id<>listing_id and l.zip=original.zip and l.status<>'sold' and not l.hidden and l.list_price between original.list_price*.7 and original.list_price*1.3 order by abs(l.list_price-original.list_price) limit 4$$;
create function public.check_rate_limit(bucket text,max_hits int default 10,window_seconds int default 60) returns boolean language plpgsql security definer set search_path='' as $$declare n int;begin insert into private.rate_limits as r(key,hits,window_start) values(bucket,1,now()) on conflict(key) do update set hits=case when r.window_start<now()-make_interval(secs=>window_seconds) then 1 else r.hits+1 end,window_start=case when r.window_start<now()-make_interval(secs=>window_seconds) then now() else r.window_start end returning hits into n;return n<=max_hits;end$$;
revoke all on function public.check_rate_limit(text,int,int) from public,anon,authenticated;
grant execute on function public.check_rate_limit(text,int,int) to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('listing-photos','listing-photos',true,10485760,array['image/jpeg','image/png','image/webp','image/avif']),('brand','brand',true,5242880,array['image/svg+xml','image/png','image/webp']),('agents','agents',true,5242880,array['image/jpeg','image/png','image/webp']),('blog','blog',true,10485760,array['image/jpeg','image/png','image/webp']),('neighborhoods','neighborhoods',true,10485760,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy content_images_read on storage.objects for select to anon,authenticated using(bucket_id in ('listing-photos','brand','agents','blog','neighborhoods'));
create policy staff_image_write on storage.objects for all to authenticated using(bucket_id in ('listing-photos','brand','agents','blog','neighborhoods') and (select private.is_staff())) with check(bucket_id in ('listing-photos','brand','agents','blog','neighborhoods') and (select private.is_staff()));
